function formatDispatchDay(dispatch){
  const {placed_epoch_ms,facility_zone,day_code_map,cutoffs=[],closed_dates=[],before_cutoff_policy,after_cutoff_policy,closed_date_policy,date_format,display_pattern}=dispatch;
  const parts=new Intl.DateTimeFormat("en-US",{timeZone:facility_zone,year:"numeric",month:"2-digit",day:"2-digit",weekday:"short",hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(new Date(placed_epoch_ms));
  const values=Object.fromEntries(parts.filter(({type})=>type!=="literal").map(({type,value})=>[type,value]));
  const weekdayByNumber=Object.fromEntries(Object.entries(day_code_map).map(([code,number])=>[number,code]));
  const currentDate=new Date(Date.UTC(Number(values.year),Number(values.month)-1,Number(values.day)));
  const currentCode=weekdayByNumber[["SUN","MON","TUE","WED","THU","FRI","SAT"].indexOf(values.weekday.toUpperCase())+1];
  const cutoff=cutoffs.find(({day_code})=>day_code===currentCode);
  const beforeCutoff=cutoff&&Number(values.hour)*60+Number(values.minute)<cutoff.minute_of_day;
  let selectedDate=currentDate;
  if((beforeCutoff?before_cutoff_policy:after_cutoff_policy)==="next_open_day"){
